const account = $input.first().json;

const storyTypes = Array.isArray(account.storyTypes) ? account.storyTypes : JSON.parse(account.storyTypes || '[]');
const storyType = storyTypes[Math.floor(Math.random() * storyTypes.length)] || 'motivational';

const voiceMap = {
  male: 'en-US-ChristopherNeural',
  female: 'en-US-JennyNeural'
};
const voice = voiceMap[(account.voiceType || 'male').toLowerCase()] || 'en-US-ChristopherNeural';

// Per-account visual style suffix appended to every image prompt for consistency.
// Stored on TikTokAccount.imageStyleSuffix; falls back to a cinematic default.
const styleSuffix = account.imageStyleSuffix || 'cinematic film still, photorealistic, dramatic lighting, 9:16 vertical composition, ultra detailed, depth of field';

const jobId = `${account.id}_${Date.now()}`;

return [{
  json: { ...account, storyType, voice, styleSuffix, jobId }
}];

const raw = ($input.first().json.text || '').trim();
if (!raw) throw new Error('LLM returned empty response');

// Strip any accidental markdown fences
let jsonStr = raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();

let parsed;
try {
  parsed = JSON.parse(jsonStr);
} catch (e) {
  // Try to extract first {...} block
  const m = jsonStr.match(/\{[\s\S]*\}/);
  if (!m) throw new Error('LLM output is not JSON: ' + jsonStr.slice(0, 200));
  parsed = JSON.parse(m[0]);
}

const script = (parsed.script || '').trim();
const scenes = Array.isArray(parsed.scenes) ? parsed.scenes : [];
if (!script) throw new Error('LLM returned no script');
if (!scenes.length) throw new Error('LLM returned no scenes');

const ctx = $('Prepare Job').first().json;

return scenes.map((s, i) => ({
  json: {
    ...ctx,
    partText: (s.text || '').trim(),
    visualPrompt: (s.visual_prompt || s.visualPrompt || '').trim(),
    partIndex: i,
    totalParts: scenes.length,
    fullScript: script
  }
}));

// Input has N items, each with ttsUrl and imageB64 (added by earlier HTTP nodes via merge)
const items = $input.all();
const sorted = items.slice().sort((a, b) => (a.json.partIndex || 0) - (b.json.partIndex || 0));

const audioUrls = sorted.map(it => ({ audio_url: it.json.ttsUrl }));
const imagesBase64 = sorted.map(it => it.json.imageB64);

const ctx = $('Prepare Job').first().json;
return [{
  json: {
    ...ctx,
    audioUrls,
    imagesBase64,
    fullScript: sorted[0].json.fullScript,
    totalParts: sorted.length
  }
}];

const mergedUrl = $input.first().json.url;
const ctx = $('Collect Scenes').first().json;
return [{ json: { ...ctx, ttsUrl: mergedUrl } }];

