const raw = ($input.first().json.text || '').trim();
let caption = '', hashtags = [];
try {
  // Strip code fences if present
  const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  const parsed = JSON.parse(cleaned);
  caption = String(parsed.caption || '').trim();
  hashtags = Array.isArray(parsed.hashtags) ? parsed.hashtags.filter(Boolean) : [];
} catch (e) {
  // Fallback: try loose extraction
  const capM = raw.match(/\"caption\"\s*:\s*\"([^\"]+)\"/);
  const tagsM = raw.match(/\"hashtags\"\s*:\s*\[([^\]]+)\]/);
  if (capM) caption = capM[1];
  if (tagsM) hashtags = tagsM[1].split(',').map(s => s.replace(/["\s]/g, '')).filter(Boolean);
}
// Sanitize hashtags
hashtags = hashtags.map(h => {
  const tag = String(h).trim().toLowerCase().replace(/\s+/g, '');
  return tag.startsWith('#') ? tag : '#' + tag.replace(/[^a-z0-9_]/g, '');
}).filter(h => h.length > 1);
if (!caption) caption = 'Watch till the end';
if (hashtags.length === 0) hashtags = ['#fyp', '#foryou', '#storytime'];
return [{ json: { caption, hashtags } }];
